contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint lockTime, uint putAmount, uint minSum, uint collectAmount) public payable {
        require(address(this).balance >= putAmount);

        // Initialize MinSum before the contract is initialized.
        c.SetMinSum(minSum);

        // Make the test contract the caller of c and give it a positive balance/unlock time.
        c.Put{value: putAmount}(lockTime);

        // Read the state made visible by the public getter before Collect.
        (uint unlockTimeBefore, uint balanceBefore) = c.Acc(address(this));

        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint unlockTimeAfter, uint balanceAfter) = c.Acc(address(this));

        // General rule: Collect can succeed only when the preconditions in the source are met.
        // We express the postcondition via the public getter: if the call completed, the
        // pre-state must have been eligible for collection.  If it reverted, no claim is made
        // about the pre-state (it may have reverted because the preconditions failed or because
        // the external LogFile call failed).
        assert(reverted || (balanceBefore >= minSum && balanceBefore >= collectAmount && block.timestamp > unlockTimeBefore));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint lockTime, uint putAmount, uint minSum, uint collectAmount) public payable {
        require(address(this).balance >= putAmount);

        // Configure MinSum and provide a funded locked account for the test contract.
        c.SetMinSum(minSum);
        c.Put{value: putAmount}(lockTime);

        // The contract may be uninitialized, which is fine: Collect does not check it.
        (uint unlockTimeBefore, uint balanceBefore) = c.Acc(address(this));
        uint cBalanceBefore = address(c).balance;

        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint unlockTimeAfter, uint balanceAfter) = c.Acc(address(this));
        uint cBalanceAfter = address(c).balance;

        bool eligible = (balanceBefore >= minSum && balanceBefore >= collectAmount && block.timestamp > unlockTimeBefore);

        // General rule: success iff the source-level preconditions held;
        // on success the account balance and the contract Ether balance decrease by exactly collectAmount;
        // on revert both balances are unchanged.
        assert(
            reverted
                ? (balanceAfter == balanceBefore && unlockTimeAfter == unlockTimeBefore && cBalanceAfter == cBalanceBefore)
                : (eligible && balanceAfter == balanceBefore - collectAmount && cBalanceAfter == cBalanceBefore - collectAmount)
        );
    }

    receive() external payable {}
}

